import { useEffect,useState } from 'react'
import { useNavigate,useParams } from 'react-router-dom'
import api from '../../services/api'
import LoadingSpinner from '../../components/LoadingSpinner'
export default function EditProduct(){const {id}=useParams();const nav=useNavigate();const [form,setForm]=useState(null);useEffect(()=>{api.get(`/api/vendor/products/${id}`).then(({data})=>setForm(data))},[id]);if(!form)return <LoadingSpinner/>;function update(e){setForm({...form,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value})}async function save(e){e.preventDefault();await api.patch(`/api/vendor/products/${id}`,{...form,price:Number(form.price),stock_quantity:Number(form.stock_quantity)});nav('/vendor/products')}return <div className="form-page"><span className="section-kicker">Catalog management</span><h1 className="vendor-title">Edit Product</h1><form className="vendor-form" onSubmit={save}>{['name','description','category','price','stock_quantity'].map(name=><label key={name}>{name.replace('_',' ')}{name==='description'?<textarea name={name} value={form[name]} onChange={update} required/>:<input name={name} type={['price','stock_quantity'].includes(name)?'number':'text'} value={form[name]} onChange={update} required/>}</label>)}<label className="toggle"><input type="checkbox" checked={form.is_available} onChange={update} name="is_available"/> Available</label><button className="auth-submit">Save Changes</button></form></div>}
